INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63122332', 63122332, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Modal Printer Dot Matrik', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 74750207, 'January 2026', 'APBD', 1, 1, '7 Unit', 'Uraian pekerjaan Pengadaan Printer Epson LQ-2190 ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan unit printer dot matrix tipe Epson LQ-2190 untuk mendukung kelancaran kegiatan administrasi perkantoran, khususnya pencetakan dokumen berkelanjutan, formulir rangkap, dan dokumen keuangan/arsip yang memerlukan hasil cetak stabil dan tahan lama. Pekerjaan ini mencakup penyediaan printer Epson LQ-2190 yang memenuhi spesifikasi teknis, memiliki performa andal, kompatibel dengan sistem kerja perkantoran, serta sesuai untuk penggunaan intensif. Printer yang disediakan harus dalam kondisi baru, bukan rekondisi, dan dilengkapi dengan aksesoris standar pabrikan', 'Spesifikasi Teknis Pengadaan Printer Epson LQ-2190 1. Nama Barang Printer Dot Matrix Epson LQ-2190 2. Jenis Barang Peralatan Teknologi Informasi dan Komunikasi (Perangkat Cetak) 3. Merek / Tipe Merek: Epson Tipe/Model: LQ-2190 4. Jenis Printer Dot Matrix 24-pin 5. Fungsi Pencetakan dokumen administrasi Pencetakan formulir berkelanjutan Pencetakan kertas rangkap (continuous form dan multipart) 6. Kecepatan Cetak Hingga 576 karakter per detik (cps) Mode cetak draft dan near letter quality (NLQ) 7. Resolusi Cetak Hingga 360 x 180 dpi 8. Lebar Media Cetak Maksimal 136 kolom Mendukung kertas lebar hingga A3 / continuous form 9. Jenis dan Ketebalan Kertas Continuous form Single sheet Multipart form (hingga ± 6 rangkap, termasuk 1 asli + 5 salinan) 10. Antarmuka / Konektivitas USB Parallel (IEEE 1284) 11. Konsumsi Daya Tegangan: 220–240 VAC, 50/60 Hz Konsumsi daya hemat sesuai standar pabrikan 12. Sistem Operasi yang Didukung Windows (versi umum yang masih didukung driver Epson) Kompatibel dengan sistem aplikasi perkantoran 13. Pita Printer (Ribbon) Menggunakan Ribbon Epson original atau setara Umur pita panjang dan mudah diganti 14. Kondisi Barang Baru (bukan bekas/rekondisi) Asli pabrikan Belum pernah digunakan 15. Kelengkapan Unit printer Kabel daya Ribbon printer Buku petunjuk/manual Kartu garansi resmi 16. Garansi Garansi resmi pabrikan minimal 1 (satu) tahun 17. Standar Mutu Memenuhi standar mutu dan spesifikasi pabrikan Epson Cocok untuk penggunaan intensif perkantoran 18. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 19. Tempat dan Waktu Pengiriman Lokasi: Sesuai ketentuan PPK/Pejabat Pengadaan Waktu: Sesuai jadwal dalam kontrak/SP 20. Pemeriksaan dan Serah Terima Dilakukan oleh PPK Dibuktikan dengan Berita Acara Serah Terima (BAST) Disertai uji fungsi dasar (power on dan cetak)', 12450207, 'low', NULL, NULL, NULL, 1, 0, 1, 0, 1, 677025);
