INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63122387', 63122387, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI ANDOOLO', 'Pengadaan Outsourcing Tenaga Keamanan dan Kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Tenggara, Konawe Selatan (Kab.)', 391404000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '13 bulan', 'URAIAN PEKERJAAN PENGADAAN OUTSOURCING SATPAM DAN CLEANING SERVICE Pekerjaan ini merupakan pengadaan jasa outsourcing Jasa Keamanan (Satpam) dan Jasa kebersihan (Cleaning Service) pada Pengadilan Negeri Andoolo Tahun Anggaran 2026 guna mendukung kelancaran operasional perkantoran, keamanan lingkungan, serta kebersihan dan kenyamanan fasilitas kerja dan pelayanan publik. Lingkup pekerjaan meliputi penyediaan tenaga Satpam sebanyak 4 (empat) orang dan tenaga Cleaning Service sebanyak 4(empat) orang selama 13 (tiga belas) bulan, termasuk pengelolaan tenaga kerja, pembayaran upah, pemenuhan kewajiban ketenagakerjaan (BPJS Kesehatan dan BPJS Ketenagakerjaan), pemberian Tunjangan Hari Raya (THR), serta penyediaan perlengkapan kerja yang diperlukan. Penyedia bertanggung jawab menjamin ketersediaan, disiplin, dan kinerja tenaga kerja sesuai standar operasional yang ditetapkan serta mengganti tenaga kerja yang tidak memenuhi persyaratan selama masa kontrak', 'Memiliki Pengalaman Pekerjaan: a) Penyediaan barang pada divisi (Lihat Tabel) yang sama paling kurang 1 pekerjaan dalam kurun waktu 1 (satu) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; b) Penyediaan barang sekurang-kurangnya dalam kelompok/grup (Lihat Tabel) yang sama paling kurang 1 pekerjaan dalam kurun waktu 3 (tiga) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; c) Untuk usaha nonkecil memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir sebesar paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran dan d) Untuk usaha kecil/koperasi yang mengikuti paket pengadaan untuk usaha nonkecil, memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir sebesar paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 678206);
